const ESTACION = 'CAMPO DE MARTE';
const fechaCaptura = new Date().toISOString();

const PARAMETROS = [
  { fragmento: 'pm2', parametro: 'pm25' },
  { fragmento: 'pm10', parametro: 'pm10' },
  { fragmento: 'so2', parametro: 'so2' },
  { fragmento: 'no2', parametro: 'no2' },
  { fragmento: 'o3', parametro: 'o3' },
];

function normalizar(txt) {
  return String(txt || '').trim().toLowerCase().replace(/\s/g, '');
}

function excelSerialAFecha(serial) {
  const utcMs = Date.UTC(1899, 11, 30) + Math.round(serial) * 86400000;
  const d = new Date(utcMs);
  return { anio: d.getUTCFullYear(), mes: String(d.getUTCMonth()+1).padStart(2,'0'), dia: String(d.getUTCDate()).padStart(2,'0') };
}

function excelSerialAHora(serial) {
  const totalMinutos = Math.round(serial * 24 * 60);
  const horas = String(Math.floor(totalMinutos/60)%24).padStart(2,'0');
  const minutos = String(totalMinutos%60).padStart(2,'0');
  return `${horas}:${minutos}`;
}

const filas = $input.all().map((item) => item.json);
if (filas.length === 0) return [];

const todasLasClaves = new Set();
for (const f of filas) for (const k of Object.keys(f)) todasLasClaves.add(k);

const claveFechaExiste = [...todasLasClaves].some((k) => normalizar(k).includes('fecha'));

let filasDatos, mapaColumnas;

if (claveFechaExiste) {
  mapaColumnas = {};
  for (const clave of todasLasClaves) mapaColumnas[clave] = normalizar(clave);
  filasDatos = filas;
} else {
  let indiceEncabezado = -1;
  for (let i = 0; i < filas.length; i++) {
    const valores = Object.values(filas[i]).map(normalizar);
    if (valores.includes('fecha')) { indiceEncabezado = i; break; }
  }
  if (indiceEncabezado === -1) throw new Error('No se encontro la fila de encabezado.');
  mapaColumnas = {};
  for (const [claveOriginal, valorCelda] of Object.entries(filas[indiceEncabezado])) {
    mapaColumnas[claveOriginal] = normalizar(valorCelda);
  }
  filasDatos = filas.slice(indiceEncabezado + 1);
}

function encontrarClave(fragmento) {
  return Object.entries(mapaColumnas).find(([, nombreReal]) => nombreReal.includes(fragmento))?.[0];
}

const claveFecha = encontrarClave('fecha');
const claveHora = encontrarClave('hora');
if (!claveFecha || !claveHora) throw new Error('No se pudieron ubicar las columnas Fecha/Hora.');

const columnasParametro = PARAMETROS
  .map((p) => ({ ...p, clave: encontrarClave(p.fragmento) }))
  .filter((p) => p.clave);

const resultado = [];

for (const fila of filasDatos) {
  const fechaCruda = fila[claveFecha];
  const horaCruda = fila[claveHora];
  if (fechaCruda === undefined || fechaCruda === '' || horaCruda === undefined || horaCruda === '') continue;

  let anio, mes, dia, horaStr;
  if (typeof fechaCruda === 'number') {
    ({ anio, mes, dia } = excelSerialAFecha(fechaCruda));
  } else {
    [dia, mes, anio] = String(fechaCruda).split('/');
  }
  if (!dia || !mes || !anio) continue;

  horaStr = typeof horaCruda === 'number' ? excelSerialAHora(horaCruda) : String(horaCruda);

  const medidoEn = new Date(`${anio}-${mes}-${dia}T${horaStr}:00-05:00`).toISOString();

  for (const { parametro, clave } of columnasParametro) {
    const crudo = fila[clave];
    if (crudo === undefined || crudo === '') continue;
    const valor = parseFloat(String(crudo).replace(',', '.'));
    if (isNaN(valor)) continue;
    resultado.push({ json: { estacion: ESTACION, parametro, valor, medido_en: medidoEn, fecha_captura: fechaCaptura } });
  }
}

return resultado;
